        out = {s: 0 for s in STATUSES}
        for rec in self.data.values():
            out[rec["status"]] = out.get(rec["status"], 0) + 1
        out["verified_built"] = sum(1 for r in self.data.values() if r["status"] == "built" and r["verified"])
        return out

